"""Growth：本金增长计算（模拟考场提供的第三方包）。"""


def simple(p, r, n):
    """单利：本金 p，年利率 r（如 0.03），n 年后的本息和"""
    return p * (1 + r * n)


def compound(p, r, n):
    """复利：本金 p，年利率 r，n 年后的本息和"""
    return p * (1 + r) ** n

"""Geo2D：平面几何小工具（模拟考场提供的第三方包）。"""
import math


def dist(x1, y1, x2, y2):
    """两点间距离"""
    return math.hypot(x2 - x1, y2 - y1)


def heron(a, b, c):
    """海伦公式求三角形面积（三边 a、b、c）"""
    s = (a + b + c) / 2
    v = s * (s - a) * (s - b) * (s - c)
    return math.sqrt(v) if v > 0 else 0.0

"""MathPlus：数论小工具（模拟考场提供的第三方包）。"""


def fact(n):
    """n 的阶乘"""
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r


def is_prime(n):
    """n 是否为素数"""
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True
